def execute(arguments):
    """
    文本处理工具

    参数:
        arguments (dict): 包含以下字段
            - text (str): 要处理的文本，必填
            - operation (str): 操作类型，"split"（分割）、"replace"（替换）、"findall"（查找所有）、"match"（匹配）
            - pattern (str): 正则表达式模式，split/replace/findall/match 操作必填
            - replacement (str): 替换内容，replace 操作时使用
            - flags (list): 正则标志，如 ["ignore_case", "multiline", "dotall"]

    返回:
        dict: 包含处理结果的字典
            - success (bool): 是否成功
            - result (any): 处理结果
            - count (int): 结果数量（split/findall时）
            - matched (bool): 是否匹配（match时）
            - groups (tuple): 匹配组（match时）
            - error (str): 错误信息（失败时）
    """
    import re

    text = arguments.get("text", "")
    operation = arguments.get("operation", "split")
    pattern = arguments.get("pattern", "")
    replacement = arguments.get("replacement", "")
    flags = arguments.get("flags", [])

    if not text:
        return {"success": False, "error": "请提供要处理的文本"}

    try:
        re_flags = 0
        if "ignore_case" in flags:
            re_flags |= re.IGNORECASE
        if "multiline" in flags:
            re_flags |= re.MULTILINE
        if "dotall" in flags:
            re_flags |= re.DOTALL

        if operation == "split":
            if not pattern:
                return {"success": False, "error": "请提供分割模式"}
            result = re.split(pattern, text, flags=re_flags)
            return {"success": True, "result": result, "count": len(result)}

        elif operation == "replace":
            if not pattern:
                return {"success": False, "error": "请提供匹配模式"}
            result = re.sub(pattern, replacement, text, flags=re_flags)
            return {"success": True, "result": result}

        elif operation == "findall":
            if not pattern:
                return {"success": False, "error": "请提供匹配模式"}
            result = re.findall(pattern, text, flags=re_flags)
            return {"success": True, "result": result, "count": len(result)}

        elif operation == "match":
            if not pattern:
                return {"success": False, "error": "请提供匹配模式"}
            match = re.search(pattern, text, flags=re_flags)
            if match:
                return {
                    "success": True,
                    "matched": True,
                    "result": match.group(),
                    "groups": match.groups(),
                    "start": match.start(),
                    "end": match.end()
                }
            else:
                return {"success": True, "matched": False}

        else:
            return {"success": False, "error": f"未知的操作: {operation}"}
    except re.error as e:
        return {"success": False, "error": f"正则表达式错误: {str(e)}"}
    except Exception as e:
        return {"success": False, "error": str(e)}
